+/// A catalog end mill: the running data under every derived tool.
+fn base() -> Tool {
+    catalog()
+        .into_iter()
+        .map(|(_, t)| t)
+        .find(|t| t.kind == ToolKind::EndMill)
+        .unwrap_or_else(|| panic!("the catalog has no end mill"))
+}
+
+fn near(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
